{"action":"write_file","path":"expr.test.js","content":"'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { evaluate } = require('./expr');

test('precedence of * over +', () => {
  assert.equal(evaluate('1 + 2 * 3'), 7);
});

test('parentheses', () => {
  assert.equal(evaluate('(1 + 2) * 3'), 9);
});

test('division', () => {
  assert.equal(evaluate('10 / 4'), 2.5);
});

test('numbers and fractional parts', () => {
  assert.equal(evaluate('3'), 3);
  assert.equal(evaluate('3.25'), 3.25);
  assert.equal(evaluate('.5'), 0.5);
});

test('whitespace ignored', () => {
  assert.equal(evaluate('  1   +   2 * 3  '), 7);
});

test('unary operators and repetition', () => {
  assert.equal(evaluate('-3'), -3);
  assert.equal(evaluate('+3'), 3);
  assert.equal(evaluate('--3'), 3);
  assert.equal(evaluate('---3'), -3);
  assert.equal(evaluate('++3'), 3);
});

test('power operator right-associative and unary sign in exponent', () => {
  assert.equal(evaluate('2 ^ 3 ^ 2'), 512);
  assert.equal(evaluate('2 ^ -1'), 0.5);
  assert.equal(evaluate('-2 ^ 2'), -4);
});

test('multiplicative operators and remainder', () => {
  assert.equal(evaluate('6 % 4'), 2);
  assert.equal(evaluate('-5 % 3'), -2);
  assert.equal(evaluate('10 * 3 / 2'), 15);
});

test('division and remainder by zero throws RangeError', () => {
  assert.throws(() => evaluate('5 / 0'), RangeError);
  assert.throws(() => evaluate('5 % 0'), RangeError);
});

test('syntax errors', () => {
  assert.throws(() => evaluate(''), SyntaxError);
  assert.throws(() => evaluate('   '), SyntaxError);
  assert.throws(() => evaluate('(1 + 2'), SyntaxError);
  assert.throws(() => evaluate('1 + 2)'), SyntaxError);
  assert.throws(() => evaluate('3.'), SyntaxError);
  assert.throws(() => evaluate('1 2'), SyntaxError);
  assert.throws(() => evaluate('a'), SyntaxError);
});

test('type error', () => {
  assert.throws(() => evaluate(123), TypeError);
  assert.throws(() => evaluate(null), TypeError);
});
"}
